"""
インタラクティブ問題 ローカルテスター (Interactive Judge Tester)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
AtCoder等のインタラクティブ問題 (対話型問題) をローカルで自動テストするための通信マネージャ。
解答プログラム (子プロセス) とジャッジ (Judgeクラス) を標準入出力パイプで接続し、自動対話検証を行う。

【使い方】
1. テスト対象のスクリプトパスと Python 実行ファイルパスを指定
2. Judge クラスで初回の入力 (N や Q など) と、各クエリに対する応答・判定ロジックを実装
3. tester.run(judge) を実行
"""

import sys
from subprocess import PIPE, Popen

# https://github.com/ddfkit/acsampl/blob/main/interactive.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class InteractiveTester:
    def __init__(self,py_cmd,target_script):
        self.cmd=[py_cmd,target_script]
    def run(self,judge):
        p=Popen(self.cmd,stdin=PIPE,stdout=PIPE,stderr=PIPE,text=True)
        init_data=judge.init_input()
        if init_data:p.stdin.write(init_data+"\n");p.stdin.flush()
        while p.poll() is None:
            line=p.stdout.readline()
            if not line:break
            line=line.strip()
            resp,done=judge.respond(line)
            if resp is not None:p.stdin.write(resp+"\n");p.stdin.flush()
            if done:break
        p.terminate()
        return judge.verdict()

# https://github.com/ddfkit/acsampl/blob/main/interactive.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
class MockJudge:
    def __init__(self,ans):
        self.ans=ans;self.cnt=0;self.ok=False
    def init_input(self):return "1 100"
    def respond(self,query):
        self.cnt+=1
        op,*args=query.split();val=int(args[0])
        if op=="?":
            return ("1" if val<=self.ans else "0"),False
        elif op=="!":
            self.ok=(val==self.ans);return None,True
        return None,True
    def verdict(self):return self.ok,self.cnt

if __name__ == "__main__":
    j = MockJudge(ans=42)
    lo, hi = 1, 100
    while lo < hi:
        mid = (lo + hi + 1) // 2
        resp, _ = j.respond(f"? {mid}")
        if resp == "1": lo = mid
        else: hi = mid - 1
    _, done = j.respond(f"! {lo}")
    ok, queries = j.verdict()
    assert ok and queries <= 8
    print("interactive.py: tests passed!")
